  return {
    rect: { top: rect.top, left: rect.left, width: rect.width, height: rect.height },
    onClickDefined: typeof btn.onclick,
    hasReactProps: !!reactProps,
    propsKeys: reactProps ? Object.keys(reactProps) : []
  };
});
